import BuildsFilters from '../components/common/BuildsFilters/BuildsFilters.container'
import BuildPager from '../components/common/Pager/BuildPager/BuildPager.container'
import {useBooleanQueryParam} from '../hooks/routes'

import BuildLineLayout from './BuildLineLayout'
import BuildsFetcher from './BuildsFetcher'
import BuildsWithLastReadyLocator from './BuildsWithLastReadyLocator'

export type AllBuildsProps = {
  locatorHelpUrl?: string
}

export default function AllBuilds({locatorHelpUrl}: AllBuildsProps) {
  const useRawLocator = useBooleanQueryParam('use-raw-locator')
  const withPager = !useRawLocator
  return (
    <BuildsFetcher
      withPager={withPager}
      withQueued={useRawLocator}
      withRunning={useRawLocator}
      withBuildTypeDetails
      withBuildDetails
      updatePeriod={null}
    >
      <BuildsFilters
        withStateFilter
        withProjectBuildtypeFilter
        locatorHelpUrl={locatorHelpUrl}
        withBuildsInNewWindowLink
        showUpdateResults
        withPager={withPager}
      />
      <BuildLineLayout>
        <BuildsWithLastReadyLocator withPager={withPager} withLoader showOverlayOnLoading />
      </BuildLineLayout>
      {withPager && <BuildPager />}
    </BuildsFetcher>
  )
}
